pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 newMinSum) internal {
        vm.assume(true);
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        try c.SetMinSum(newMinSum) {} catch { return; }
        uint256 minAfter;
        try c.MinSum() returns (uint256 __r) { minAfter = __r; } catch { return; }
        assertTrue(minAfter == newMinSum);
    }

    function testFuzz_run(uint256 newMinSum) public {
        _run(newMinSum);
    }

    receive() external payable {}
}
